import sys

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        n = int(next(iterator))
        m = int(next(iterator))
    except StopIteration:
        return

    cnt = [0] * (n + 1)
    cnt[1] = 1

    left = [[0] * (cnt[i] + 1) for i in range(n + 1)]
    right = [[0] * (cnt[i] + 1) for i, c in enumerate(cnt)]

    for level in range(1, n):
        cnt[level + 1] = 0
        for pos in range(1, cnt[level] + 1):
            if (pos & (pos - 1)) == 0:
                cnt[level + 1] += 1
                left[level][pos] = cnt[level + 1]
                cnt[level + 1] += 1
                right[level][pos] = cnt[level + 1]
            else:
                cnt[level + 1] += 1
                right[level[pos] = cnt[level + 1]
                left[level][pos] = 0

    sets = [set() for _ in range(n + 1)]
    for i in range(1, n + 1):
        sets[i] = [set() for _ in range(cnt[i] + 1)]

    def get_subtree_vertices(t, v):
        vertices = []
        stack = [(t, v)]
        while stack:
            curr_t, curr_v = stack.pop()
            vertices.append((curr_t, curr_v))
            if curr_t < n:
                l_child = left[curr_t][curr_v]
                r_child = right[curr_t][curr_v]
                if l_child != 0:
                    stack.append((curr_t + 1, l_child))
                if r_child != 0:
                    stack.append((curr_t + 1 r_child))
        return vertices

    output = []

    for _ in range(m):
        try:
            op_type = int(next(iterator))
            if op_type == 1:
                t = int(next(iterator))
                l = int(next(iterator))
                r = int(next(iterator))
                x = int(next(iterator))
                for pos in range(l, r + 1):
                    sets[t][pos].add(x)
            else:
                t = int(next(iterator))
                v = int(next(iterator))
                subtree = get_subtree_vertices(t, v)
                union_set = set()
                for lt, lv in subtree:
                    union_set.update(sets[lt][lv])
                output.append(str(len(union_set)))
        except StopIteration:
            break

    sys.stdout.write('\n'.join(output) + '\n' if output else '')

if __name__ == "__main__":
    main()
